  "admin.academyHub.infoNote": "Supabase ডাটাবেস থেকে সরাসরি শিক্ষার্থী ও তাদের বিশ্লেষণ পড়া হয় (সব ব্যবহারকারীর মধ্যে বাস্তব ডেটা)। কোর্স, সনদ এবং ইনস্ট্রাক্টরের ডেটা লোকালি তৈরি (পর্ব ৩–৬) হলেও প্রতিটি ব্যবহারকারীর নিজস্ব ব্রাউজারে সংরক্ষিত থাকে—তাই এখানে সম্পূর্ণ তালিকা হিসেবে দেখা যায় না; এটি কোনো বাগ নয়, বর্তমান আর্কিটেকচার সীমাবদ্ধতা, এবং এই সিস্টেমগুলো বাস্তব ডাটাবেসের সঙ্গে যুক্ত হলে সমাধান হবে।",
